    MIX_SECOND_3_GOT: begin b <= (product+accum+32768)>>>16; state <= MIX_SECOND_4; end
    MIX_SECOND_4: begin sadr <= O+i; swdata <= b; swe <= 1; state <= MIX_END; end
    MIX_END: begin if(i+1 >= 64) begin state <= EXPERT_END; end else begin i<=i+1; state <= MIX; end end
    EXPERT_END: begin if(rank==0) begin rank<=1;coef0<=coeff;state <= EXPERT; end else state <= ADD_FFN; end
    ADD_FFN: begin  back_ADD <= NEXT_LAYER; state <= ADD; end
    NEXT_LAYER: begin if(layer==4) state <= OUTPUT; else begin layer<=layer+1;lbase<=lbase+307840;state <= LAYER; end end
    OUTPUT: begin nbase <= 32768; back_NORM <= OUTPUT_1; state <= NORM; end
    OUTPUT_1: begin mbase <= 21'd0+0; src <= Z; dst <= LGT; rows<=512; cols<=64; back_MAT <= OUTPUT_2; state <= MAT; end
    OUTPUT_2: begin best0<=-64'sh7fffffffffffffff;i<=0; state <= ARGMAX; end
    ARGMAX: begin sadr <= LGT+i; state <= ARGMAX_FETCH; end
    ARGMAX_FETCH: begin  state <= ARGMAX_GOT; end
    ARGMAX_GOT: begin a <= $signed(srdata); state <= ARGMAX_1; end
    ARGMAX_1: begin if(a>best0) begin best0<=a;winner<=i;end state <= ARG_END; end
    ARG_END: begin if(i+1 >= 512) begin state <= COMMIT; end else begin i<=i+1; state <= ARGMAX; end end
    COMMIT: begin pos<=pos+1;next_token<=winner;rep_valid<=1;rep_kind<=is_step?2:1;rep_token<=is_step?tok:0; state <= IDLE; end
    FAILED: begin rep_valid<=1;rep_kind<=3;rep_token<=0; state <= IDLE; end
    MAT: begin r<=0; wi<=mbase; state <= MAT_ROW; end
    MAT_ROW: begin j<=0;accum<=0; state <= MAT_MAC; end
    MAT_MAC: begin sadr <= src+j; state <= MAT_MAC_FETCH; end
    MAT_MAC_FETCH: begin  state <= MAT_MAC_GOT; end
    MAT_MAC_GOT: begin a <= $signed(srdata); state <= MAT_MAC_1; end
    MAT_MAC_1: begin waddr <= wi; wreq <= 1; state <= MAT_MAC_1_WAIT; end
    MAT_MAC_1_WAIT: begin if(wfail) begin wreq<=0; state <= FAILED; end else if(wvalid) begin wreq<=0; b <= $signed(wdata); state <= MAT_MAC_2; end end
    MAT_MAC_2: begin ma <= a; mb <= b; state <= MAT_MAC_2_M; end
    MAT_MAC_2_M: begin  state <= MAT_MAC_2_GOT; end
    MAT_MAC_2_GOT: begin accum <= accum+product; state <= MAT_MAC_3; end
    MAT_MAC_3: begin wi<=wi+1; state <= MAT_J; end
    MAT_J: begin if(j+1 >= cols) begin state <= MAT_WRITE; end else begin j<=j+1; state <= MAT_MAC; end end
    MAT_WRITE: begin sadr <= dst+r; swdata <= (accum+16384)>>>15; swe <= 1; state <= MAT_R; end
    MAT_R: begin if(r+1 >= rows) begin state <= MAT_RET; end else begin r<=r+1; state <= MAT_ROW; end end
    MAT_RET: begin state <= back_MAT; end
    ADD: begin i<=0; state <= ADD_I; end
    ADD_I: begin sadr <= X+i; state <= ADD_I_FETCH; end
    ADD_I_FETCH: begin  state <= ADD_I_GOT; end
    ADD_I_GOT: begin a <= $signed(srdata); state <= ADD_I_1; end
    ADD_I_1: begin sadr <= O+i; state <= ADD_I_1_FETCH; end
    ADD_I_1_FETCH: begin  state <= ADD_I_1_GOT; end
    ADD_I_1_GOT: begin b <= $signed(srdata); state <= ADD_I_2; end
    ADD_I_2: begin sadr <= X+i; swdata <= a+b; swe <= 1; state <= ADD_END; end
    ADD_END: begin if(i+1 >= 64) begin state <= ADD_RET; end else begin i<=i+1; state <= ADD_I; end end
    ADD_RET: begin state <= back_ADD; end
    NORM: begin i<=0; accum<=0; state <= NORM_SS; end
    NORM_SS: begin sadr <= X+i; state <= NORM_SS_FETCH; end
    NORM_SS_FETCH: begin  state <= NORM_SS_GOT; end
    NORM_SS_GOT: begin a <= $signed(srdata); state <= NORM_SS_1; end
    NORM_SS_1: begin ma <= a; mb <= a; state <= NORM_SS_1_M; end
    NORM_SS_1_M: begin  state <= NORM_SS_1_GOT; end
    NORM_SS_1_GOT: begin accum <= accum+product; state <= NORM_SS_END; end
    NORM_SS_END: begin if(i+1 >= 64) begin state <= SQRT_START; end else begin i<=i+1; state <= NORM_SS; end end
    SQRT_START: begin rad<=(accum>>>6)+42950; root<=0; rems<=0; bitcount<=0; state <= SQRT; end
    SQRT: begin rad<=rad<<2; rems<=sqrt_cand>=sqrt_trial ? sqrt_cand-sqrt_trial : sqrt_cand;root<=(root<<1)+(sqrt_cand>=sqrt_trial); if(bitcount==31) state <= NORM_SCALE; else bitcount<=bitcount+1; end
    NORM_SCALE: begin i<=0; state <= NORM_I; end
    NORM_I: begin sadr <= X+i; state <= NORM_I_FETCH; end
    NORM_I_FETCH: begin  state <= NORM_I_GOT; end
    NORM_I_GOT: begin a <= $signed(srdata); state <= NORM_I_1; end
    NORM_I_1: begin waddr <= nbase+i; wreq <= 1; state <= NORM_I_1_WAIT; end
    NORM_I_1_WAIT: begin if(wfail) begin wreq<=0; state <= FAILED; end else if(wvalid) begin wreq<=0; b <= $signed(wdata); state <= NORM_I_2; end end
    NORM_I_2: begin ma <= a; mb <= b; state <= NORM_I_2_M; end
    NORM_I_2_M: begin  state <= NORM_I_2_GOT; end
    NORM_I_2_GOT: begin c <= product<<<4; state <= NORM_I_3; end
    NORM_I_3: begin num <= c; den <= root; state <= NORM_I_3_GO; end
    NORM_I_3_GO: begin back_DIV <= NORM_I_3_DONE; state <= DIV; end
    NORM_I_3_DONE: begin a <= quo; state <= NORM_I_4; end
    NORM_I_4: begin sadr <= Z+i; swdata <= a; swe <= 1; state <= NORM_END; end
    NORM_END: begin if(i+1 >= 64) begin state <= NORM_RET; end else begin i<=i+1; state <= NORM_I; end end
    NORM_RET: begin state <= back_NORM; end
    ROT: begin i<=0; state <= ROT_PAIR; end
    ROT_PAIR: begin sadr <= rbase+i; state <= ROT_PAIR_FETCH; end
    ROT_PAIR_FETCH: begin  state <= ROT_PAIR_GOT; end
    ROT_PAIR_GOT: begin a <= $signed(srdata); state <= ROT_PAIR_1; end
    ROT_PAIR_1: begin sadr <= rbase+i+1; state <= ROT_PAIR_1_FETCH; end
    ROT_PAIR_1_FETCH: begin  state <= ROT_PAIR_1_GOT; end
    ROT_PAIR_1_GOT: begin b <= $signed(srdata); state <= ROT_PAIR_2; end
    ROT_PAIR_2: begin rotaddr<=((pos<<2)+((i>>1)&3)); state <= ROT_PAIR_3; end
    ROT_PAIR_3: begin  state <= ROT_PAIR_4; end
    ROT_PAIR_4: begin ma <= a; mb <= cosq; state <= ROT_PAIR_4_M; end
    ROT_PAIR_4_M: begin  state <= ROT_PAIR_4_GOT; end
    ROT_PAIR_4_GOT: begin c <= product; state <= ROT_PAIR_5; end
    ROT_PAIR_5: begin ma <= b; mb <= sinq; state <= ROT_PAIR_5_M; end
    ROT_PAIR_5_M: begin  state <= ROT_PAIR_5_GOT; end
    ROT_PAIR_5_GOT: begin d <= (c-product+16384)>>>15; state <= ROT_PAIR_6; end
    ROT_PAIR_6: begin sadr <= rbase+i; swdata <= d; swe <= 1; state <= ROT_PAIR_7; end
    ROT_PAIR_7: begin ma <= a; mb <= sinq; state <= ROT_PAIR_7_M; end
    ROT_PAIR_7_M: begin  state <= ROT_PAIR_7_GOT; end
    ROT_PAIR_7_GOT: begin c <= product; state <= ROT_PAIR_8; end
    ROT_PAIR_8: begin ma <= b; mb <= cosq; state <= ROT_PAIR_8_M; end
    ROT_PAIR_8_M: begin  state <= ROT_PAIR_8_GOT; end
    ROT_PAIR_8_GOT: begin d <= (c+product+16384)>>>15; state <= ROT_PAIR_9; end
    ROT_PAIR_9: begin sadr <= rbase+i+1; swdata <= d; swe <= 1; state <= ROT_END; end
    ROT_END: begin if(i+2>=rlen) state <= back_ROT; else begin i<=i+2;state <= ROT_PAIR; end end
    SOFT: begin i<=0;esum<=0; state <= SOFT_I; end
    SOFT_I: begin sadr <= softbase+i; state <= SOFT_I_FETCH; end
    SOFT_I_FETCH: begin  state <= SOFT_I_GOT; end
    SOFT_I_GOT: begin a <= $signed(srdata); state <= SOFT_I_1; end
    SOFT_I_1: begin exaddr <= ((maxv-a) >= 1048576) ? 4096 : (((maxv-a) + 128) >>> 8); state <= SOFT_I_1_L; end
    SOFT_I_1_L: begin  state <= SOFT_I_1_G; end
    SOFT_I_1_G: begin b <= exp_q; state <= SOFT_I_2; end
    SOFT_I_2: begin sadr <= softbase+i; swdata <= b; swe <= 1; state <= SOFT_I_3; end
    SOFT_I_3: begin esum<=esum+b; state <= SOFT_END_I; end
    SOFT_END_I: begin if(i+1 >= softlen) begin state <= SOFT_SCALE; end else begin i<=i+1; state <= SOFT_I; end end
    SOFT_SCALE: begin i<=0; state <= SOFT_J; end
    SOFT_J: begin sadr <= softbase+i; state <= SOFT_J_FETCH; end
    SOFT_J_FETCH: begin  state <= SOFT_J_GOT; end
    SOFT_J_GOT: begin a <= $signed(srdata); state <= SOFT_J_1; end
    SOFT_J_1: begin num <= a<<<16; den <= esum; state <= SOFT_J_1_GO; end
    SOFT_J_1_GO: begin back_DIV <= SOFT_J_1_DONE; state <= DIV; end
    SOFT_J_1_DONE: begin b <= quo; state <= SOFT_J_2; end
    SOFT_J_2: begin sadr <= softbase+i; swdata <= b; swe <= 1; state <= SOFT_END_J; end
    SOFT_END_J: begin if(i+1 >= softlen) begin state <= SOFT_RET; end else begin i<=i+1; state <= SOFT_J; end end
    SOFT_RET: begin state <= back_SOFT; end
    DIV: begin signednum<=num+$signed({1'b0,den[62:1]}); state <= DIV_GO; end
    DIV_GO: begin neg<=signednum<0; dividend<=signednum<0 ? -signednum : signednum; drem<=0;quot<=0;bitcount<=0; state <= DIV_BIT; end
    DIV_BIT: begin dividend<=dividend<<1;drem<=div_cand>=den ? div_cand-den : div_cand;quot<=(quot<<1)+(div_cand>=den); if(bitcount==63) state <= DIV_DONE; else bitcount<=bitcount+1; end
    DIV_DONE: begin quo<=neg ? -$signed(quot)-(drem!=0) : $signed(quot);state <= back_DIV; end
    default: begin state<=FAILED;wreq<=0;end
 endcase
end
